package com.resilientgeo.mesh.trust

import org.json.JSONObject
import java.time.Instant

/** `fixtures/rescue-requests-v0.json`, generated by pipeline/tools/generate-rescue-fixture.mjs. */
object RescueFixtures {
    val root: JSONObject by lazy {
        val text = checkNotNull(RescueFixtures::class.java.classLoader?.getResourceAsStream("fixtures/rescue-requests-v0.json")) {
            "missing test resource: fixtures/rescue-requests-v0.json"
        }.bufferedReader().use { it.readText() }
        JSONObject(text)
    }

    val now: Instant get() = Instant.parse(root.getString("now"))

    fun deviceKey(): DeviceSigningKey = CrowdFixtures.deviceKey(root.getJSONObject("seeds").getString("device"))

    fun otherKey(): DeviceSigningKey = CrowdFixtures.deviceKey(root.getJSONObject("seeds").getString("other"))

    fun cases(key: String): List<JSONObject> {
        val list = root.getJSONArray(key)
        return (0 until list.length()).map { JSONObject(list.getJSONObject(it).toString()) }
    }

    fun eventCase(name: String): JSONObject =
        cases("event_cases").first { it.getString("name") == name }.getJSONObject("event")
}
